challenge:ch-adv-lazy-pipeline.solution:
function* lazyMap(iterable, fn) {
  let i = 0;
  for (const value of iterable) {
    yield fn(value, i);
    i += 1;
  }
}

function* lazyFilter(iterable, predicate) {
  let i = 0;
  for (const value of iterable) {
    if (predicate(value, i)) yield value;
    i += 1;
  }
}

function toArray(iterable) {
  const out = [];
  for (const value of iterable) out.push(value);
  return out;
}

tests.body:
let calls = 0;
const pipeline = lazyMap([1, 2, 3], (n) => { calls += 1; return n; });
expect(calls).toBe(0);
toArray(pipeline);
expect(calls).toBe(3);

const order = [];
const pipeline = lazyFilter(
  lazyMap([1, 2], (n) => { order.push("map " + n); return n; }),
  (n) => { order.push("filter " + n); return true; },
);
toArray(pipeline);
expect(order).toEqual(["map 1", "filter 1", "map 2", "filter 2"]);

function* naturals() { let n = 0; for (;;) { yield n; n += 1; } }
const pipeline = lazyFilter(lazyMap(naturals(), (n) => n * 2), (n) => n % 3 === 0);
const out = [];
for (const value of pipeline) { out.push(value); if (out.length === 4) break; }
expect(out).toEqual([0, 6, 12, 18]);

let calls = 0;
function* naturals() { let n = 0; for (;;) { yield n; n += 1; } }
const pipeline = lazyMap(naturals(), (n) => { calls += 1; return n; });
for (const value of pipeline) { if (value === 4) break; }
expect(calls).toBe(5);

