challenge:ch-adv-tree-generator.solution:
function* walk(node) {
  yield node.value;
  for (const child of node.children ?? []) {
    yield* walk(child);
  }
}

function findFirst(node, predicate) {
  for (const value of walk(node)) {
    if (predicate(value)) return value;
  }
  return undefined;
}

