challenge:ch-adv-proxy-validate.solution:
function validated(target, rules) {
  return new Proxy(target, {
    get(object, property, receiver) {
      if (typeof property === "symbol" || property in object) {
        return Reflect.get(object, property, receiver);
      }
      throw new TypeError("no such property: " + String(property));
    },
    set(object, property, value, receiver) {
      const rule = rules[property];
      if (rule && !rule(value)) {
        throw new TypeError("invalid value for " + String(property) + ": " + String(value));
      }
      return Reflect.set(object, property, value, receiver);
    },
  });
}

