challenge:ch-adv-proxy-negative-index.solution:
function wrapIndex(array) {
  return new Proxy(array, {
    get(target, property, receiver) {
      if (typeof property === "string") {
        const index = Number(property);
        if (Number.isInteger(index) && index < 0) {
          return target[target.length + index];
        }
      }
      return Reflect.get(target, property, receiver);
    },
  });
}

challenge:ch-adv-default-map.solution:
function defaultMap(createDefault) {
  const entries = new Map();
  return {
    get(key) {
      if (!entries.has(key)) entries.set(key, createDefault(key));
      return entries.get(key);
    },
    set(key, value) {
      entries.set(key, value);
      return this;
    },
    has(key) {
      return entries.has(key);
    },
    delete(key) {
      return entries.delete(key);
    },
    get size() {
      return entries.size;
    },
    entries() {
      return entries.entries();
    },
  };
}

challenge:ch-adv-deep-clone.solution:
function deepClone(value, seen = new Map()) {
  if (value === null || typeof value !== "object") return value;
  if (seen.has(value)) return seen.get(value);

  if (value instanceof Date) {
    const copy = new Date(value.getTime());
    seen.set(value, copy);
    return copy;
  }

  if (value instanceof Map) {
    const copy = new Map();
    seen.set(value, copy);
    for (const [k, v] of value) copy.set(deepClone(k, seen), deepClone(v, seen));
    return copy;
  }

  if (value instanceof Set) {
    const copy = new Set();
    seen.set(value, copy);
    for (const v of value) copy.add(deepClone(v, seen));
    return copy;
  }

  if (Array.isArray(value)) {
    const copy = [];
    seen.set(value, copy);
    for (const v of value) copy.push(deepClone(v, seen));
    return copy;
  }

  const copy = {};
  seen.set(value, copy);
  for (const key of Object.keys(value)) copy[key] = deepClone(value[key], seen);
  return copy;
}

challenge:ch-adv-tagged-template.solution:
function safe(strings, ...values) {
  const entities = {
    "&": "&amp;",
    "<": "&lt;",
    ">": "&gt;",
    '"': "&quot;",
    "'": "&#39;",
  };
  const escape = (value) => {
    if (value === null || value === undefined) return "";
    return String(value).replace(/[&<>"']/g, (char) => entities[char]);
  };

  let out = strings[0];
  for (let i = 0; i < values.length; i += 1) {
    out += escape(values[i]) + strings[i + 1];
  }
  return out;
}

challenge:ch-adv-symbol-protocol.solution:
const SYMBOLS = { USD: "$", EUR: "€", GBP: "£" };

class Money {
  #cents;

  #currency;

  constructor(cents, currency = "USD") {
    this.#cents = cents;
    this.#currency = currency;
    Object.freeze(this);
  }

  get cents() {
    return this.#cents;
  }

  get currency() {
    return this.#currency;
  }

  [Symbol.toPrimitive](hint) {
    if (hint === "number") return this.#cents;
    const prefix = SYMBOLS[this.#currency] ?? this.#currency + " ";
    return prefix + (this.#cents / 100).toFixed(2);
  }

  get [Symbol.toStringTag]() {
    return "Money";
  }

  *[Symbol.iterator]() {
    yield this.#cents;
    yield this.#currency;
  }
}

class Currency {
  static [Symbol.hasInstance](value) {
    return value instanceof Object && value.constructor === Money && value.currency === this.code;
  }
}

