challenge:ch-algo-brackets.solution:
function isBalanced(text) {
  const pairs = { ")": "(", "]": "[", "}": "{" };
  const opens = new Set(Object.values(pairs));
  const stack = [];
  for (const char of text) {
    if (opens.has(char)) {
      stack.push(char);
    } else if (Object.hasOwn(pairs, char)) {
      if (stack.pop() !== pairs[char]) return false;
    }
  }
  return stack.length === 0;
}

challenge:ch-algo-group-anagrams.solution:
function groupAnagrams(words) {
  const groups = new Map();
  for (const word of words) {
    const key = [...word].sort().join("");
    const bucket = groups.get(key);
    if (bucket === undefined) groups.set(key, [word]);
    else bucket.push(word);
  }
  return [...groups.values()];
}

