challenge:ch-algo-permutations.solution:
function permutations(items) {
  if (items.length === 0) return [[]];
  const out = [];
  for (let i = 0; i < items.length; i += 1) {
    const rest = [...items.slice(0, i), ...items.slice(i + 1)];
    for (const sub of permutations(rest)) {
      out.push([items[i], ...sub]);
    }
  }
  return out;
}

challenge:ch-algo-quickselect.solution:
function kthSmallest(values, k) {
  if (k < 1 || k > values.length) return null;

  function select(list, rank) {
    const pivot = list[Math.floor(Math.random() * list.length)];
    const below = [];
    const equal = [];
    const above = [];
    for (const value of list) {
      if (value < pivot) below.push(value);
      else if (value > pivot) above.push(value);
      else equal.push(value);
    }
    if (rank <= below.length) return select(below, rank);
    if (rank <= below.length + equal.length) return pivot;
    return select(above, rank - below.length - equal.length);
  }

  return select(values, k);
}

