challenge:ch-algo-topological.solution:
function buildOrder(graph) {
  const names = Object.keys(graph);
  const outstanding = new Map();
  const dependents = new Map();
  for (const name of names) {
    outstanding.set(name, graph[name].length);
    dependents.set(name, []);
  }
  for (const name of names) {
    for (const dep of graph[name]) dependents.get(dep).push(name);
  }

  const order = [];
  const placed = new Set();
  let progress = true;
  while (progress) {
    progress = false;
    for (const name of names) {
      if (placed.has(name) || outstanding.get(name) !== 0) continue;
      placed.add(name);
      order.push(name);
      for (const dependent of dependents.get(name)) {
        outstanding.set(dependent, outstanding.get(dependent) - 1);
      }
      progress = true;
      break;
    }
  }

  return order.length === names.length ? order : null;
}

