challenge:ch-arr-intersection.solution:
function intersection(a, b) {
  const inB = new Set(b);
  const seen = new Set();
  const out = [];
  for (const value of a) {
    if (inB.has(value) && !seen.has(value)) {
      seen.add(value);
      out.push(value);
    }
  }
  return out;
}

