challenge:ch-arr-sort-by.solution:
function sortBy(items, ...keyFns) {
  return [...items].sort((left, right) => {
    for (const keyFn of keyFns) {
      const a = keyFn(left);
      const b = keyFn(right);
      if (a < b) return -1;
      if (a > b) return 1;
    }
    return 0;
  });
}

