  if (step === 0) throw new RangeError("step must not be zero");
  const out = [];
  if (step > 0) {
    for (let n = start; n < end; n += step) out.push(n);
  } else {
    for (let n = start; n > end; n += step) out.push(n);
  }
  return out;
}

