challenge:ch-arr-moving-average.solution:
function movingAverage(values, span) {
  if (span > values.length) return [];
  let total = 0;
  for (let i = 0; i < span; i += 1) total += values[i];
  const out = [total / span];
  for (let i = span; i < values.length; i += 1) {
    total += values[i] - values[i - span];
    out.push(total / span);
  }
  return out;
}

