challenge:ch-arr-transpose.solution:
function transpose(matrix) {
  if (matrix.length === 0) return [];
  const width = matrix[0].length;
  for (const row of matrix) {
    if (row.length !== width) throw new TypeError("matrix rows must all be the same length");
  }
  const out = [];
  for (let c = 0; c < width; c += 1) {
    const column = [];
    for (let r = 0; r < matrix.length; r += 1) column.push(matrix[r][c]);
    out.push(column);
  }
  return out;
}

challenge:ch-arr-spiral.solution:
function spiralOrder(matrix) {
  if (matrix.length === 0 || matrix[0].length === 0) return [];
  const out = [];
  let top = 0;
  let bottom = matrix.length - 1;
  let left = 0;
  let right = matrix[0].length - 1;

  while (top <= bottom && left <= right) {
    for (let c = left; c <= right; c += 1) out.push(matrix[top][c]);
    top += 1;

    for (let r = top; r <= bottom; r += 1) out.push(matrix[r][right]);
    right -= 1;

    if (top <= bottom) {
      for (let c = right; c >= left; c -= 1) out.push(matrix[bottom][c]);
      bottom -= 1;
    }

    if (left <= right) {
      for (let r = bottom; r >= top; r -= 1) out.push(matrix[r][left]);
      left += 1;
    }
  }
  return out;
}

