challenge:ch-arr-chunk-while.solution:
function chunkWhile(items, shouldContinue) {
  if (items.length === 0) return [];
  const out = [];
  let run = [items[0]];
  for (let i = 1; i < items.length; i += 1) {
    if (shouldContinue(items[i - 1], items[i])) {
      run.push(items[i]);
    } else {
      out.push(run);
      run = [items[i]];
    }
  }
  out.push(run);
  return out;
}

