challenge:ch-async-all-settled.solution:
function allSettled(items) {
  return new Promise((resolve) => {
    const results = new Array(items.length);
    let remaining = items.length;
    if (remaining === 0) {
      resolve([]);
      return;
    }
    const settle = (index, descriptor) => {
      results[index] = descriptor;
      remaining -= 1;
      if (remaining === 0) resolve(results);
    };
    items.forEach((item, index) => {
      Promise.resolve(item).then(
        (value) => settle(index, { status: "fulfilled", value }),
        (reason) => settle(index, { status: "rejected", reason }),
      );
    });
  });
}

