challenge:ch-async-retry.solution:
async function retry(task, { attempts, wait, shouldRetry }) {
  let lastError;
  for (let attempt = 1; attempt <= attempts; attempt += 1) {
    try {
      return await task();
    } catch (error) {
      lastError = error;
      if (!shouldRetry(error)) throw error;
      if (attempt < attempts) await wait(attempt);
    }
  }
  throw lastError;
}

