challenge:ch-async-timeout.solution:
function withTimeout(promise, ms, schedule) {
  return new Promise((resolve, reject) => {
    const cancel = schedule(() => reject(new Error("timed out")), ms);
    promise.then(
      (value) => {
        cancel();
        resolve(value);
      },
      (error) => {
        cancel();
        reject(error);
      },
    );
  });
}

