challenge:ch-async-fetch-json.solution:
async function getJson(url, { fetch }) {
  let response;
  try {
    response = await fetch(url);
  } catch (cause) {
    const error = new Error("network request failed", { cause });
    error.kind = "network";
    throw error;
  }

  if (!response.ok) {
    const error = new Error("request failed with status " + response.status);
    error.kind = "http";
    error.status = response.status;
    throw error;
  }

  try {
    return await response.json();
  } catch (cause) {
    const error = new Error("response was not valid JSON", { cause });
    error.kind = "parse";
    throw error;
  }
}

