challenge:ch-beg-swap-case.solution:
function swapCase(text) {
  let out = "";
  for (const char of text) {
    const lower = char.toLowerCase();
    const upper = char.toUpperCase();
    if (char === lower && char !== upper) out += upper;
    else if (char === upper && char !== lower) out += lower;
    else out += char;
  }
  return out;
}

