  let min = numbers[0];
  let max = numbers[0];
  for (let i = 1; i < numbers.length; i += 1) {
    if (numbers[i] < min) min = numbers[i];
    if (numbers[i] > max) max = numbers[i];
  }
  return { min, max };
}

