  if (lastTwo >= 11 && lastTwo <= 13) return n + "th";
  const lastOne = n % 10;
  if (lastOne === 1) return n + "st";
  if (lastOne === 2) return n + "nd";
  if (lastOne === 3) return n + "rd";
  return n + "th";
}

