challenge:ch-cls-iterable-range.solution:
class Range {
  constructor(start, end, step = 1) {
    this.start = start;
    this.end = end;
    this.step = step;
  }

  get length() {
    return Math.max(0, Math.ceil((this.end - this.start) / this.step));
  }

  has(value) {
    const offset = value - this.start;
    if (offset % this.step !== 0) return false;
    const index = offset / this.step;
    return index >= 0 && index < this.length;
  }

  *[Symbol.iterator]() {
    if (this.step > 0) {
      for (let n = this.start; n < this.end; n += this.step) yield n;
    } else {
      for (let n = this.start; n > this.end; n += this.step) yield n;
    }
  }
}

