challenge:ch-cls-result.solution:
class Result {
  #ok;

  #value;

  #error;

  constructor(ok, value, error) {
    this.#ok = ok;
    this.#value = value;
    this.#error = error;
  }

  static ok(value) {
    return new Result(true, value, undefined);
  }

  static err(error) {
    return new Result(false, undefined, error);
  }

  static from(fn) {
    try {
      return Result.ok(fn());
    } catch (error) {
      return Result.err(error);
    }
  }

  get isOk() {
    return this.#ok;
  }

  get isErr() {
    return !this.#ok;
  }

  unwrap() {
    if (!this.#ok) throw this.#error;
    return this.#value;
  }

  unwrapOr(fallback) {
    return this.#ok ? this.#value : fallback;
  }

  map(fn) {
    return this.#ok ? Result.ok(fn(this.#value)) : this;
  }
}

