challenge:ch-cls-mixin.solution:
function Serializable(Base) {
  return class extends Base {
    toJSON() {
      return { ...this };
    }
  };
}

function Timestamped(Base) {
  return class extends Base {
    constructor(...args) {
      super(...args);
      const options = args[0] ?? {};
      this.createdAt = options.now ? options.now() : 0;
    }

    age(now) {
      return now - this.createdAt;
    }
  };
}

