challenge:ch-ds-queue-two-stacks.solution:
class Queue {
  #inbound = [];

  #outbound = [];

  get size() {
    return this.#inbound.length + this.#outbound.length;
  }

  #transfer() {
    if (this.#outbound.length > 0) return;
    while (this.#inbound.length > 0) {
      this.#outbound.push(this.#inbound.pop());
    }
  }

  enqueue(value) {
    this.#inbound.push(value);
  }

  dequeue() {
    this.#transfer();
    return this.#outbound.pop();
  }

  peek() {
    this.#transfer();
    return this.#outbound[this.#outbound.length - 1];
  }
}

