challenge:ch-ds-trie.solution:
class Trie {
  #root = { children: new Map(), isWord: false };

  insert(word) {
    let node = this.#root;
    for (const char of word) {
      if (!node.children.has(char)) {
        node.children.set(char, { children: new Map(), isWord: false });
      }
      node = node.children.get(char);
    }
    node.isWord = true;
  }

  #find(prefix) {
    let node = this.#root;
    for (const char of prefix) {
      node = node.children.get(char);
      if (node === undefined) return null;
    }
    return node;
  }

  has(word) {
    const node = this.#find(word);
    return node !== null && node.isWord;
  }

  startingWith(prefix) {
    const start = this.#find(prefix);
    if (start === null) return [];
    const out = [];
    const walk = (node, built) => {
      if (node.isWord) out.push(built);
      for (const char of [...node.children.keys()].sort()) {
        walk(node.children.get(char), built + char);
      }
    };
    walk(start, prefix);
    return out;
  }
}

