challenge:ch-dom-form-values.solution:
function readForm(form) {
  const fields = [...form.elements].filter((el) => el.name);
  const nameCounts = new Map();
  for (const el of fields) nameCounts.set(el.name, (nameCounts.get(el.name) ?? 0) + 1);

  const out = {};
  for (const el of fields) {
    if (el.type === "radio") {
      if (!Object.hasOwn(out, el.name)) out[el.name] = null;
      if (el.checked) out[el.name] = el.value;
    } else if (el.type === "checkbox") {
      if (nameCounts.get(el.name) > 1) {
        if (!Object.hasOwn(out, el.name)) out[el.name] = [];
        if (el.checked) out[el.name].push(el.value);
      } else {
        out[el.name] = el.checked;
      }
    } else {
      out[el.name] = el.value;
    }
  }
  return out;
}

