challenge:ch-dom-observer-cleanup.solution:
function watchText(element, onChange) {
  let last = element.textContent;
  let stopped = false;

  const observer = new MutationObserver(() => {
    if (stopped) return;
    const text = element.textContent;
    if (text === last) return;
    last = text;
    onChange(text);
  });

  observer.observe(element, { characterData: true, childList: true, subtree: true });

  return function stop() {
    if (stopped) return;
    stopped = true;
    observer.disconnect();
  };
}

