challenge:ch-dom-virtual-diff.solution:
function syncList(container, items, createNode) {
  const existing = new Map();
  for (const child of container.children) existing.set(child.dataset.id, child);

  const used = new Set();
  for (const item of items) {
    let node = existing.get(item.id);
    if (node) {
      if (node.textContent !== item.label) node.textContent = item.label;
    } else {
      node = createNode(item);
    }
    used.add(item.id);
    container.appendChild(node);
  }

  for (const [id, node] of existing) {
    if (!used.has(id)) node.remove();
  }
}

