challenge:ch-sec-safe-redirect.solution:
function safeRedirect(next, allowedOrigins) {
  const FALLBACK = "/";
  if (typeof next !== "string" || next === "") return FALLBACK;

  if (next.startsWith("/")) {
    const second = next[1];
    if (second === "/" || second === "\\") return FALLBACK;
    return next;
  }

  let url;
  try {
    url = new URL(next);
  } catch {
    return FALLBACK;
  }
  return allowedOrigins.includes(url.origin) ? next : FALLBACK;
}

