function safeFileName(input) {
  const substituted = String(input).replace(/[^A-Za-z0-9._-]/g, "_");
  const withoutLeadingDots = substituted.replace(/^\.+/, "");
  const capped = withoutLeadingDots.slice(0, 100);
  return capped === "" ? "unnamed" : capped;
}

challenge:ch-sec-rate-limit.solution:
class TokenBucket {
  #capacity;

  #refillPerSecond;

  #tokens;

  #lastUpdate = null;

  constructor(capacity, refillPerSecond) {
    this.#capacity = capacity;
    this.#refillPerSecond = refillPerSecond;
    this.#tokens = capacity;
  }

  #available(now) {
    if (this.#lastUpdate === null) this.#lastUpdate = now;
    const elapsed = Math.max(0, now - this.#lastUpdate);
    return Math.min(this.#capacity, this.#tokens + (elapsed / 1000) * this.#refillPerSecond);
  }

  tryConsume(now, count = 1) {
    const available = this.#available(now);
    if (count > available) return false;
    this.#tokens = available - count;
    this.#lastUpdate = Math.max(this.#lastUpdate, now);
    return true;
  }
}

