challenge:ch-eng-batch-writes.solution:
function createBatcher(loadMany, schedule) {
  let pending = new Map();

  async function flush() {
    const batch = pending;
    pending = new Map();
    const ids = [...batch.keys()];
    try {
      const values = await loadMany(ids);
      ids.forEach((id, i) => {
        for (const waiter of batch.get(id)) waiter.resolve(values[i]);
      });
    } catch (error) {
      for (const waiters of batch.values()) {
        for (const waiter of waiters) waiter.reject(error);
      }
    }
  }

  return function load(id) {
    return new Promise((resolve, reject) => {
      if (pending.size === 0) schedule(flush);
      if (!pending.has(id)) pending.set(id, []);
      pending.get(id).push({ resolve, reject });
    });
  };
}

