function withContext(message, error) {
  return new Error(message + ": " + error.message, { cause: error });
}

function rootCause(error) {
  const seen = new Set();
  let current = error;
  while (current.cause instanceof Error && !seen.has(current.cause)) {
    seen.add(current);
    current = current.cause;
  }
  return current;
}

function describeChain(error) {
  const seen = new Set();
  const out = [];
  let current = error;
  while (current instanceof Error && !seen.has(current)) {
    seen.add(current);
    out.push(current.message);
    current = current.cause;
  }
  return out;
}

