challenge:ch-exp-cancellable-pool.solution:
async function runPool(items, limit, worker, signal) {
  signal.throwIfAborted();
  const results = new Array(items.length);
  let cursor = 0;

  async function runner() {
    for (;;) {
      signal.throwIfAborted();
      const index = cursor;
      if (index >= items.length) return;
      cursor += 1;
      results[index] = await worker(items[index], signal, index);
    }
  }

  const runners = [];
  for (let i = 0; i < Math.min(limit, items.length); i += 1) runners.push(runner());
  await Promise.all(runners);
  return results;
}

