challenge:ch-exp-lfu.solution:
class LFUCache {
  #capacity;

  #entries = new Map();

  #buckets = new Map();

  #minCount = 0;

  constructor(capacity) {
    this.#capacity = capacity;
  }

  get size() {
    return this.#entries.size;
  }

  #bucket(count) {
    if (!this.#buckets.has(count)) this.#buckets.set(count, new Map());
    return this.#buckets.get(count);
  }

  #touch(key, entry) {
    const from = this.#bucket(entry.count);
    from.delete(key);
    if (from.size === 0) {
      this.#buckets.delete(entry.count);
      if (this.#minCount === entry.count) this.#minCount = entry.count + 1;
    }
    entry.count += 1;
    this.#bucket(entry.count).set(key, true);
  }

  get(key) {
    const entry = this.#entries.get(key);
    if (entry === undefined) return undefined;
    this.#touch(key, entry);
    return entry.value;
  }

  set(key, value) {
    if (this.#capacity < 1) return;
    const existing = this.#entries.get(key);
    if (existing !== undefined) {
      existing.value = value;
      this.#touch(key, existing);
      return;
    }
    if (this.#entries.size >= this.#capacity) {
      const victims = this.#bucket(this.#minCount);
      const oldest = victims.keys().next().value;
      victims.delete(oldest);
      if (victims.size === 0) this.#buckets.delete(this.#minCount);
      this.#entries.delete(oldest);
    }
    this.#entries.set(key, { value, count: 1 });
    this.#bucket(1).set(key, true);
    this.#minCount = 1;
  }
}

