challenge:ch-exp-json-patch.solution:
function applyPatch(document, operations) {
  const clone = (v) => {
    if (Array.isArray(v)) return v.map(clone);
    if (typeof v === "object" && v !== null) {
      const copy = {};
      for (const k of Object.keys(v)) copy[k] = clone(v[k]);
      return copy;
    }
    return v;
  };

  const parse = (pointer) =>
    pointer.split("/").slice(1).map((s) => s.replace(/~1/g, "/").replace(/~0/g, "~"));

  const working = clone(document);

  for (const operation of operations) {
    const segments = parse(operation.path);
    const last = segments.pop();
    let parent = working;
    for (const segment of segments) {
      if (parent === null || typeof parent !== "object" || !(segment in parent)) {
        throw new Error("path not found: " + operation.path);
      }
      parent = parent[segment];
    }

    const isArray = Array.isArray(parent);
    if (operation.op === "add") {
      if (isArray) {
        const index = last === "-" ? parent.length : Number(last);
        if (!Number.isInteger(index) || index < 0 || index > parent.length) {
          throw new Error("bad array index: " + operation.path);
        }
        parent.splice(index, 0, operation.value);
      } else {
        parent[last] = operation.value;
      }
    } else {
      if (!(last in parent)) throw new Error("path not found: " + operation.path);
      if (operation.op === "remove") {
        if (isArray) parent.splice(Number(last), 1);
        else delete parent[last];
      } else if (operation.op === "replace") {
        parent[last] = operation.value;
      } else if (operation.op === "test") {
        if (JSON.stringify(parent[last]) !== JSON.stringify(operation.value)) {
          throw new Error("test failed at " + operation.path);
        }
      } else {
        throw new Error("unsupported op: " + operation.op);
      }
    }
  }

  return working;
}

