challenge:ch-exp-scheduler.solution:
function createScheduler(now, yieldTo) {
  const queue = [];
  let sequence = 0;

  function schedule(priority, fn) {
    queue.push({ priority, order: sequence, fn });
    sequence += 1;
  }

  function takeNext() {
    let bestIndex = 0;
    for (let i = 1; i < queue.length; i += 1) {
      const a = queue[i];
      const b = queue[bestIndex];
      if (a.priority < b.priority || (a.priority === b.priority && a.order < b.order)) {
        bestIndex = i;
      }
    }
    return queue.splice(bestIndex, 1)[0];
  }

  async function flush(budgetMs) {
    while (queue.length > 0) {
      const sliceStart = now();
      do {
        const task = takeNext();
        try {
          task.fn();
        } catch {
          /* one failing task must not abandon the queue */
        }
      } while (queue.length > 0 && now() - sliceStart < budgetMs);

      if (queue.length > 0) {
        await new Promise((resolve) => yieldTo(resolve));
      }
    }
  }

  return { schedule, flush };
}

