challenge:ch-exp-serialize-refs.solution:
const REF = "$ref";

function encode(value) {
  const slots = [];
  const indexOf = new Map();

  function ref(v) {
    if (typeof v === "number") {
      if (Number.isNaN(v)) return { [REF]: "nan" };
      if (v === Infinity) return { [REF]: "inf" };
      if (v === -Infinity) return { [REF]: "-inf" };
      return v;
    }
    if (v === undefined) return { [REF]: "undef" };
    if (v === null || typeof v !== "object") return v;

    if (indexOf.has(v)) return { [REF]: indexOf.get(v) };
    const index = slots.length;
    indexOf.set(v, index);
    slots.push(null);

    if (v instanceof Date) slots[index] = { t: "date", v: v.getTime() };
    else if (v instanceof Map) slots[index] = { t: "map", v: [...v].map(([k, val]) => [ref(k), ref(val)]) };
    else if (v instanceof Set) slots[index] = { t: "set", v: [...v].map(ref) };
    else if (Array.isArray(v)) slots[index] = { t: "arr", v: v.map(ref) };
    else {
      const entries = {};
      for (const k of Object.keys(v)) entries[k] = ref(v[k]);
      slots[index] = { t: "obj", v: entries };
    }
    return { [REF]: index };
  }

  return { root: ref(value), slots };
}

function decode(encoded) {
  const { root, slots } = encoded;
  const built = slots.map((slot) => {
    if (slot.t === "date") return new Date(slot.v);
    if (slot.t === "map") return new Map();
    if (slot.t === "set") return new Set();
    if (slot.t === "arr") return [];
    return {};
  });

  function deref(v) {
    if (v === null || typeof v !== "object") return v;
    const marker = v[REF];
    if (marker === "undef") return undefined;
    if (marker === "nan") return NaN;
    if (marker === "inf") return Infinity;
    if (marker === "-inf") return -Infinity;
    return built[marker];
  }

  slots.forEach((slot, i) => {
    const target = built[i];
    if (slot.t === "map") for (const [k, val] of slot.v) target.set(deref(k), deref(val));
    else if (slot.t === "set") for (const val of slot.v) target.add(deref(val));
    else if (slot.t === "arr") for (const val of slot.v) target.push(deref(val));
    else if (slot.t === "obj") for (const k of Object.keys(slot.v)) target[k] = deref(slot.v[k]);
  });

  return deref(root);
}

