challenge:ch-exp-signals.solution:
let currentRunner = null;

function signal(initial) {
  let value = initial;
  const subscribers = new Set();

  const read = () => {
    if (currentRunner !== null) {
      subscribers.add(currentRunner);
      currentRunner.sources.add(subscribers);
    }
    return value;
  };

  const write = (next) => {
    if (Object.is(next, value)) return;
    value = next;
    for (const runner of [...subscribers]) runner.run();
  };

  return [read, write];
}

function createRunner(fn) {
  const runner = {
    sources: new Set(),
    run() {
      for (const subscribers of runner.sources) subscribers.delete(runner);
      runner.sources.clear();
      const previous = currentRunner;
      currentRunner = runner;
      try {
        return fn();
      } finally {
        currentRunner = previous;
      }
    },
  };
  return runner;
}

function effect(fn) {
  const runner = createRunner(fn);
  runner.run();
  return runner;
}

function computed(fn) {
  const [read, write] = signal(undefined);
  let started = false;
  return () => {
    if (!started) {
      started = true;
      effect(() => write(fn()));
    }
    return read();
  };
}

