challenge:ch-exp-produce.solution:
function produce(base, recipe) {
  const isDraftable = (v) => typeof v === "object" && v !== null;

  function createDraft(source) {
    const state = { source, copy: null, children: new Map(), modified: false };

    const target = () => state.copy ?? state.source;
    const ensureCopy = () => {
      if (state.copy === null) {
        state.copy = Array.isArray(state.source) ? state.source.slice() : { ...state.source };
      }
      state.modified = true;
      return state.copy;
    };

    const proxy = new Proxy(state.source, {
      get(_t, key) {
        const value = target()[key];
        if (!isDraftable(value)) return value;
        if (!state.children.has(key)) state.children.set(key, createDraft(value));
        return state.children.get(key).proxy;
      },
      set(_t, key, value) {
        ensureCopy()[key] = value;
        state.children.delete(key);
        return true;
      },
      deleteProperty(_t, key) {
        delete ensureCopy()[key];
        state.children.delete(key);
        return true;
      },
      has(_t, key) {
        return key in target();
      },
      ownKeys() {
        return Reflect.ownKeys(target());
      },
      getOwnPropertyDescriptor(_t, key) {
        return Reflect.getOwnPropertyDescriptor(target(), key);
      },
    });

    state.proxy = proxy;
    return state;
  }

  function finalize(state) {
    let result = state.copy;
    for (const [key, child] of state.children) {
      const finalized = finalize(child);
      if (finalized !== child.source) {
        if (result === null) {
          result = Array.isArray(state.source) ? state.source.slice() : { ...state.source };
        }
        result[key] = finalized;
      }
    }
    return result ?? state.source;
  }

  if (!isDraftable(base)) return base;
  const root = createDraft(base);
  recipe(root.proxy);
  return finalize(root);
}

