challenge:ch-exp-expression-parser.solution:
function evaluate(expression) {
  const tokens = [];
  const pattern = /\s*(\d+(?:\.\d+)?|[-+*/^()])/y;
  let at = 0;
  while (at < expression.length) {
    pattern.lastIndex = at;
    const match = pattern.exec(expression);
    if (match === null) {
      if (expression.slice(at).trim() === "") break;
      throw new SyntaxError("unexpected character at " + at);
    }
    tokens.push(match[1]);
    at = pattern.lastIndex;
  }

  let i = 0;
  const peek = () => tokens[i];
  const eat = (token) => {
    if (tokens[i] !== token) throw new SyntaxError("expected " + token);
    i += 1;
  };

  function parseSum() {
    let left = parseProduct();
    while (peek() === "+" || peek() === "-") {
      const op = tokens[i];
      i += 1;
      const right = parseProduct();
      left = op === "+" ? left + right : left - right;
    }
    return left;
  }

  function parseProduct() {
    let left = parseUnary();
    while (peek() === "*" || peek() === "/") {
      const op = tokens[i];
      i += 1;
      const right = parseUnary();
      left = op === "*" ? left * right : left / right;
    }
    return left;
  }

  function parseUnary() {
    if (peek() === "-") {
      i += 1;
      return -parseUnary();
    }
    return parsePower();
  }

  function parsePower() {
    const base = parseAtom();
    if (peek() === "^") {
      i += 1;
      return base ** parseUnary();
    }
    return base;
  }

  function parseAtom() {
    const token = peek();
    if (token === undefined) throw new SyntaxError("unexpected end of expression");
    if (token === "(") {
      i += 1;
      const value = parseSum();
      eat(")");
      return value;
    }
    if (/^\d/.test(token)) {
      i += 1;
      return Number(token);
    }
    throw new SyntaxError("unexpected token " + token);
  }

  if (tokens.length === 0) throw new SyntaxError("empty expression");
  const result = parseSum();
  if (i !== tokens.length) throw new SyntaxError("unexpected trailing input");
  return result;
}

challenge:ch-exp-glob.solution:
function matchGlob(pattern, path) {
  function matchSegment(p, s, pi = 0, si = 0) {
    if (pi === p.length) return si === s.length;
    const char = p[pi];
    if (char === "*") {
      if (matchSegment(p, s, pi + 1, si)) return true;
      return si < s.length && matchSegment(p, s, pi, si + 1);
    }
    if (si === s.length) return false;
    if (char === "?" || char === s[si]) return matchSegment(p, s, pi + 1, si + 1);
    return false;
  }

  function matchParts(pp, sp, pi = 0, si = 0) {
    if (pi === pp.length) return si === sp.length;
    if (pp[pi] === "**") {
      if (matchParts(pp, sp, pi + 1, si)) return true;
      return si < sp.length && matchParts(pp, sp, pi, si + 1);
    }
    if (si === sp.length) return false;
    if (!matchSegment(pp[pi], sp[si])) return false;
    return matchParts(pp, sp, pi + 1, si + 1);
  }

  return matchParts(pattern.split("/"), path.split("/"));
}

