challenge:ch-exp-array-diff.solution:
function diffSequences(before, after) {
  const n = before.length;
  const m = after.length;
  const lcs = Array.from({ length: n + 1 }, () => new Array(m + 1).fill(0));

  for (let i = n - 1; i >= 0; i -= 1) {
    for (let j = m - 1; j >= 0; j -= 1) {
      lcs[i][j] = before[i] === after[j]
        ? lcs[i + 1][j + 1] + 1
        : Math.max(lcs[i + 1][j], lcs[i][j + 1]);
    }
  }

  const script = [];
  let i = 0;
  let j = 0;
  while (i < n && j < m) {
    if (before[i] === after[j]) {
      script.push({ type: "keep", value: before[i] });
      i += 1;
      j += 1;
    } else if (lcs[i + 1][j] >= lcs[i][j + 1]) {
      script.push({ type: "remove", value: before[i] });
      i += 1;
    } else {
      script.push({ type: "add", value: after[j] });
      j += 1;
    }
  }
  while (i < n) {
    script.push({ type: "remove", value: before[i] });
    i += 1;
  }
  while (j < m) {
    script.push({ type: "add", value: after[j] });
    j += 1;
  }
  return script;
}

