challenge:ch-exp-router.solution:
function createRouter(routes) {
  const compiled = Object.entries(routes).map(([pattern, handler]) => ({
    handler,
    segments: pattern.split("/").filter((s) => s !== ""),
  }));

  const LITERAL = 3;
  const PARAM = 2;
  const WILD = 1;

  function tryMatch(route, parts, rawPath) {
    const params = {};
    const score = [];
    for (let i = 0; i < route.segments.length; i += 1) {
      const segment = route.segments[i];
      if (segment.startsWith("*")) {
        const rest = parts.slice(i).join("/");
        params[segment.slice(1)] = decodeURIComponent(rest);
        score.push(WILD);
        return { handler: route.handler, params, score };
      }
      if (i >= parts.length) return null;
      if (segment.startsWith(":")) {
        params[segment.slice(1)] = decodeURIComponent(parts[i]);
        score.push(PARAM);
      } else {
        if (segment !== parts[i]) return null;
        score.push(LITERAL);
      }
    }
    if (parts.length !== route.segments.length) return null;
    return { handler: route.handler, params, score };
  }

  return function match(path) {
    const parts = path.split("/").filter((s) => s !== "");
    let best = null;
    for (const route of compiled) {
      const found = tryMatch(route, parts, path);
      if (found === null) continue;
      if (best === null) {
        best = found;
        continue;
      }
      const length = Math.max(found.score.length, best.score.length);
      for (let i = 0; i < length; i += 1) {
        const a = found.score[i] ?? 0;
        const b = best.score[i] ?? 0;
        if (a !== b) {
          if (a > b) best = found;
          break;
        }
      }
    }
    if (best === null) return null;
    return { handler: best.handler, params: best.params };
  };
}

