challenge:ch-fn-debounce.solution:
function debounce(fn, delay, schedule) {
  let cancelPending = null;
  let lastArgs = null;

  const debounced = function (...args) {
    lastArgs = args;
    if (cancelPending) cancelPending();
    cancelPending = schedule(() => {
      cancelPending = null;
      fn(...lastArgs);
    }, delay);
  };

  debounced.cancel = function () {
    if (cancelPending) cancelPending();
    cancelPending = null;
  };

  return debounced;
}

