const _ = Symbol("placeholder");

function partial(fn, ...preset) {
  return function (...later) {
    const args = [];
    let next = 0;
    for (const value of preset) {
      if (value === _ && next < later.length) {
        args.push(later[next]);
        next += 1;
      } else {
        args.push(value);
      }
    }
    while (next < later.length) {
      args.push(later[next]);
      next += 1;
    }
    return fn.apply(this, args);
  };
}

