  if (numerator === 0) return [0, 1];
  let a = Math.abs(numerator);
  let b = Math.abs(denominator);
  while (b !== 0) {
    const t = b;
    b = a % b;
    a = t;
  }
  const sign = numerator * denominator < 0 ? -1 : 1;
  return [sign * (Math.abs(numerator) / a), Math.abs(denominator) / a];
}

