    if (Array.isArray(v)) return v.map(clone);
    if (isPlain(v)) {
      const copy = {};
      for (const k of Object.keys(v)) copy[k] = clone(v[k]);
      return copy;
    }
    return v;
  };

  const out = clone(base);
  for (const key of Object.keys(override)) {
    const left = out[key];
    const right = override[key];
    out[key] = isPlain(left) && isPlain(right) ? deepMerge(left, right) : clone(right);
  }
  return out;
}

