function flattenKeys(source) {
  const isContainer = (v) =>
    Array.isArray(v) || (typeof v === "object" && v !== null && Object.getPrototypeOf(v) === Object.prototype);

  const out = {};
  const walk = (value, prefix) => {
    const keys = isContainer(value) ? Object.keys(value) : [];
    if (keys.length === 0) {
      out[prefix] = value;
      return;
    }
    for (const key of keys) {
      walk(value[key], prefix === "" ? key : prefix + "." + key);
    }
  };

  for (const key of Object.keys(source)) walk(source[key], key);
  return out;
}

