    let run = 1;
    while (text[i + run] === text[i]) run += 1;
    out += text[i] + run;
    i += run;
  }
  return out;
}

function decode(encoded) {
  let out = "";
  for (const [, char, count] of encoded.matchAll(/([a-z])(\d+)/g)) {
    out += char.repeat(Number(count));
  }
  return out;
}

