challenge:ch-str-mask-card.solution:
function maskCard(number) {
  const digitCount = number.replace(/\D/g, "").length;
  if (digitCount <= 4) return number;
  let seen = 0;
  let out = "";
  for (const char of number) {
    if (char >= "0" && char <= "9") {
      seen += 1;
      out += seen <= digitCount - 4 ? "•" : char;
    } else {
      out += char;
    }
  }
  return out;
}

challenge:ch-str-query-string.solution:
function parseQuery(queryString) {
  const body = queryString.startsWith("?") ? queryString.slice(1) : queryString;
  const result = {};
  if (body === "") return result;
  const decode = (s) => decodeURIComponent(s.replace(/\+/g, " "));
  for (const pair of body.split("&")) {
    if (pair === "") continue;
    const eq = pair.indexOf("=");
    const key = decode(eq === -1 ? pair : pair.slice(0, eq));
    const value = eq === -1 ? "" : decode(pair.slice(eq + 1));
    if (!Object.hasOwn(result, key)) result[key] = value;
    else if (Array.isArray(result[key])) result[key].push(value);
    else result[key] = [result[key], value];
  }
  return result;
}

