challenge:ch-date-relative-time.solution:
function relativeTime(then, now) {
  const diff = then - now;
  const abs = Math.abs(diff);
  if (abs < 10000) return "just now";

  const units = [
    ["year", 365 * 86400000],
    ["month", 30 * 86400000],
    ["day", 86400000],
    ["hour", 3600000],
    ["minute", 60000],
    ["second", 1000],
  ];

  for (const [name, size] of units) {
    if (abs >= size) {
      const count = Math.floor(abs / size);
      const label = count + " " + name + (count === 1 ? "" : "s");
      return diff < 0 ? label + " ago" : "in " + label;
    }
  }
  return "just now";
}

