function maxWindowSum(numbers, k) {
  if (k <= 0 || numbers.length < k) return null;

  let sum = 0;
  for (let i = 0; i < k; i++) sum += numbers[i];

  let best = sum;

  for (let i = k; i < numbers.length; i++) {
    sum += numbers[i] - numbers[i - k];

    if (sum > best) best = sum;
  }

  return best;
}

