function createCache(limit) {
  const cache = new Map();

  function touch(key, value) {
    cache.delete(key);
    cache.set(key, value);
  }

  return {
    set(key, value) {
      touch(key, value);

      if (cache.size > limit) {
        cache.delete(cache.keys().next().value);
      }
    },

    get(key) {
      if (!cache.has(key)) return undefined;

      const value = cache.get(key);
      touch(key, value);

      return value;
    },

    get size() { return cache.size; },
    keys() { return [...cache.keys()]; },
  };
}

