    out.push(node.id);
    for (let i = node.replies.length - 1; i >= 0; i--) {
      stack.push(node.replies[i]);
    }
  }
  return out;
}

function breadthFirst(root) {
  const out = [];
  const queue = [root];
  let head = 0;
  while (head < queue.length) {
    const node = queue[head++];
    out.push(node.id);
    queue.push(...node.replies);
  }
  return out;
}
```

The solution:

```js
function moveZeroes(nums) {
  let write = 0;
  for (let read = 0; read < nums.length; read++) {
    if (nums[read] !== 0) {
      nums[write] = nums[read];
      write += 1;
    }
  }
  while (write < nums.length) {
    nums[write] = 0;
    write += 1;
  }
  return nums;
}
```

The fix is to make the callback lexical:

```js
this.intervalId = setInterval(() => {
  this.remaining -= 1;
  this.el.textContent = this.remaining;
}, 1000);
```

An arrow has no own `this` binding, so `this` resolves through the enclosing `start` method to the instance.

There is a second, separate bug the interviewer is probably also waiting for: the interval id is never stored, so nothing can ever stop it. The counter runs past zero into negative numbers and keeps firing after the element is gone. Store the id and clear it:

```js
stop() {
  clearInterval(this.intervalId);
  this.intervalId = null;
}
```

and clear it automatically when `remaining` reaches `0`.

The correct fix is delegation — one listener, attached once, on the stable parent:

```js
list.addEventListener("click", (event) => {
  const btn = event.target.closest(".del");
  if (!btn || !list.contains(btn)) return;
  remove(btn.closest("li"));
});
```

It works for rows that do not exist yet, costs one listener regardless of row count, and needs no cleanup when rows are removed. `closest` is what makes it robust when the click lands on an icon inside the button.

And append properly instead of re-serialising:

```js
const li = document.createElement("li");
li.textContent = item.name;
const btn = document.createElement("button");
btn.className = "del";
btn.textContent = "x";
li.append(btn);
list.append(li);
```

This is O(1) per row rather than O(n) re-parsing, and preserves everything already on the page.

The correct round trip:

```js
localStorage.setItem("profile", JSON.stringify(profile));

const raw = localStorage.getItem("profile");
const saved = raw ? JSON.parse(raw) : null;
```

`getItem` returns `null` for a missing key, and `JSON.parse(null)` returns `null` rather than throwing — but `JSON.parse` of a corrupted or truncated string throws `SyntaxError`. Storage is shared with other tabs, older versions of your app and the user's devtools, so treat it as untrusted input:

```js
function read(key, fallback) {
  try {
    const raw = localStorage.getItem(key);
    return raw === null ? fallback : JSON.parse(raw);
  } catch {
    return fallback;
  }
}
```

The modern fix is `AbortController`, which removes the need to keep references at all:

```js
let controller = null;

function openPanel() {
  controller = new AbortController();
  window.addEventListener("scroll", () => reposition(panel), { signal: controller.signal });
  panel.hidden = false;
}

function closePanel() {
  controller?.abort();
  controller = null;
  panel.hidden = true;
}
```

One `abort()` removes every listener registered with that signal, which scales cleanly when a component adds several.

The corrected implementation:

```js
function debounce(fn, wait) {
  let timer;
  return function (...args) {
    clearTimeout(timer);
    timer = setTimeout(() => fn.apply(this, args), wait);
  };
}
```

`clearTimeout(undefined)` is a harmless no-op, so the first call needs no special case.

The clearest fix expresses the intent directly:

```js
const invalid = fields.find((field) => !field.value);
return invalid ? { ok: false, field: invalid.name } : { ok: true };
```

`find` short-circuits on the first match, which is exactly the "first failure wins" semantics the original was reaching for.

A `for...of` loop also works and is preferable when the body does several things:

```js
for (const field of fields) {
  if (!field.value) return { ok: false, field: field.name };
}
return { ok: true };
```

Here `return` really does exit `validate`, and `break`/`continue` are available.

The design question an interviewer may push on: returning only the first invalid field means the user fixes one error, resubmits, and sees the next. Collecting all failures with `filter` gives a better form experience:

```js
const errors = fields.filter((f) => !f.value).map((f) => f.name);
return { ok: errors.length === 0, errors };
```

The bug that survives even after fixing the comparison: `Number("")` is `0`, and `Number("  ")` is `0`. An empty field therefore passes any numeric check. Validate emptiness separately:

```js
const raw = input.value.trim();
if (raw === "") return showError("Required");
const value = Number(raw);
if (!Number.isFinite(value)) return showError("Please enter a number");
```

The fix moves the read to the moment it is needed:

```js
button.addEventListener("click", () => {
  console.log("count is", getCount());
});
```

Now the closure captures `getCount`, a stable function, and the value is fetched fresh on each click.

A defensive version:

```js
function loadCache() {
  try {
    const raw = localStorage.getItem("cache");
    if (raw === null) return [];
    const data = JSON.parse(raw);
    return Array.isArray(data?.items) ? data.items : [];
  } catch {
    localStorage.removeItem("cache");
    return [];
  }
}
```

Note it clears the corrupt entry — otherwise the failure repeats on every load forever.

A factory that returns a handler is the other legitimate reason to see parentheses at registration:

```js
const makeHandler = (id) => (event) => handleClick(id, event);
button.addEventListener("click", makeHandler(item.id));
```

Here `makeHandler(item.id)` is called on purpose and returns the actual listener.

The fix is a regular function, whose `this` is bound by the call site:

```js
User.prototype.greet = function () {
  return `Hi, ${this.name}`;
};
```

Or the class equivalent, which does the same thing more clearly:

```js
class User {
  constructor(name) { this.name = name; }
  greet() { return `Hi, ${this.name}`; }
}
```

The fix keeps the same loop shape but changes the container:

```js
function groupByYear(records) {
  const out = new Map();
  for (const r of records) {
    if (!out.has(r.year)) out.set(r.year, []);
    out.get(r.year).push(r);
  }
  return [...out];
}
```

`Map` iterates in insertion order, keeps `year` as a number, and has no prototype keys to collide with.

Convert at the boundary, once, and validate there:

```js
const current = Number(quantityInput.value);
const added = Number(otherInput.value);

if (!Number.isFinite(current) || !Number.isFinite(added)) {
  return showError("Enter a valid quantity");
}

total.textContent = String(current + added);
```

The stack overflow needs a different fix, because a cycle has no depth at which it stops:

```js
function flatten(node, seen = new Set()) {
  if (seen.has(node)) return [];
  seen.add(node);
  const children = node.children ?? [];
  return [node.value, ...children.flatMap((child) => flatten(child, seen))];
}
```

A `Set` of visited nodes compares by reference, which is exactly right for graph identity.

Depth is the third consideration. Even an acyclic tree overflows if it is deep enough; engine stack limits are around 10,000 frames and are not part of the specification. For untrusted or deep data, convert to an explicit stack:

```js
function flatten(root) {
  const out = [];
  const seen = new Set();
  const stack = [root];
  while (stack.length > 0) {
    const node = stack.pop();
    if (seen.has(node)) continue;
    seen.add(node);
    out.push(node.value);
    const children = node.children ?? [];
    for (let i = children.length - 1; i >= 0; i--) stack.push(children[i]);
  }
  return out;
}
```

This has no recursion depth limit — it is bounded by heap, not by stack — at the cost of being longer to read. Note it also reverses the child push order to preserve left-to-right traversal.

The alternative is to be explicit about which case you are in:

```js
function renderTotal(order) {
  if (!order?.summary) {
    renderPending();
    return;
  }
  element.textContent = formatMoney(order.summary.total);
}
```

Now "not priced yet" has its own visible state, and a malformed order still throws where the mistake is.

The fix is to make time an input rather than an ambient global:

```js
test("expires 30 days after creation", () => {
  const created = new Date("2024-01-15T12:00:00Z");
  const token = createToken(created);

  expect(token.expiresAt.toISOString()).toBe("2024-02-14T12:00:00.000Z");
  expect(isExpired(token, new Date("2024-02-13T12:00:00Z"))).toBe(false);
  expect(isExpired(token, new Date("2024-02-15T12:00:00Z"))).toBe(true);
});
```

A fixed instant makes the expected value a constant you can compute by hand, and comparing ISO strings in UTC removes the timezone variable entirely.

**`BroadcastChannel`** is the purpose-built mechanism:

```js
const channel = new BroadcastChannel("auth");
channel.postMessage({ type: "logout" });
channel.addEventListener("message", (event) => {
  if (event.data.type === "logout") redirectToLogin();
});
```

Same-origin, structured-cloned messages, and the sender does not receive its own message — which is usually what you want.

The client-side guard, which should exist regardless:

```js
let inFlight = false;

form.addEventListener("submit", async (event) => {
  event.preventDefault();
  if (inFlight) return;
  inFlight = true;
  button.disabled = true;
  try {
    await createOrder(payload, { idempotencyKey });
  } finally {
    inFlight = false;
    button.disabled = false;
  }
});
```

The boolean matters as well as the `disabled` attribute, because the disable happens a frame later than a fast second click can arrive, and because the form can also be submitted with Enter.

Sending JSON requires both the header and the serialisation:

```js
await fetch("/api/orders", {
  method: "POST",
  headers: { "Content-Type": "application/json" },
  body: JSON.stringify(order),
});
```

Omit the header and many servers default to treating the body as form-encoded, parse it as one field with a bizarre name, and hand your handler an empty object. The request succeeds, the data is lost, and nothing points at the header.

The call shape:

```js
function tag(strings, ...values) {
  // strings: the literal chunks, plus strings.raw for un-escaped text
  // values:  the ${...} results, in order
}

tag`Hello ${name}, you have ${count} messages`;
```

`strings` always has exactly one more element than `values`, including empty strings at the ends when the template starts or finishes with an interpolation.

The implementation:

```js
function chunk(array, size) {
  if (!Number.isInteger(size) || size < 1) {
    throw new RangeError("size must be a positive integer");
  }

  const out = [];
  for (let i = 0; i < array.length; i += size) {
    out.push(array.slice(i, i + size));
  }
  return out;
}
```

Complexity is O(n) in total elements copied, with O(n) extra space. A generator variant avoids materialising every group at once, which matters for a very large array:

```js
function* chunks(array, size) {
  for (let i = 0; i < array.length; i += size) yield array.slice(i, i + size);
}
```

The implementations:

```js
function pick(object, keys) {
  const out = {};
  for (const key of keys) {
    if (Object.hasOwn(object, key)) out[key] = object[key];
  }
  return out;
}

function omit(object, keys) {
  const excluded = new Set(keys);
  const out = {};
  for (const key of Object.keys(object)) {
    if (!excluded.has(key)) out[key] = object[key];
  }
  return out;
}
```

Writing, without mutating the current URL:

```js
const url = new URL(location.href);
url.searchParams.set("page", String(page));
url.searchParams.delete("cursor");
history.replaceState(null, "", url);
```

`set` replaces every existing occurrence; `append` adds another. Choosing the wrong one is how a filter accumulates duplicate values on each interaction.

The implementation:

```js
function deepGet(object, path, fallback) {
  const segments = Array.isArray(path) ? path : String(path).split(".");
  let current = object;

  for (const segment of segments) {
    if (current === null || current === undefined) return fallback;
    current = current[segment];
  }

  return current === undefined ? fallback : current;
}
```

The implementation:

```js
const UNITS = [
  ["year", 31536000],
  ["month", 2592000],
  ["week", 604800],
  ["day", 86400],
  ["hour", 3600],
  ["minute", 60],
  ["second", 1],
];

function formatRelative(date, now = new Date(), locale = undefined) {
  const seconds = Math.round((date.getTime() - now.getTime()) / 1000);
  const absolute = Math.abs(seconds);

  const [unit, size] = UNITS.find(([, s]) => absolute >= s) ?? ["second", 1];
  const value = Math.round(seconds / size);

  return new Intl.RelativeTimeFormat(locale, { numeric: "auto" }).format(value, unit);
}
```

The refactor:

```js
const SHIPPING = new Map([
  ["standard",  (weight) => weight * 1.5],
  ["express",   (weight) => weight * 3 + 5],
  ["overnight", (weight) => weight * 6 + 15],
  ["pickup",    () => 0],
]);

function getShippingCost(method, weight) {
  const rate = SHIPPING.get(method);
  if (!rate) throw new RangeError(`Unknown shipping method: ${method}`);
  return rate(weight);
}
```

The cleanest seam is dependency injection: the module takes `fetch` as a parameter and defaults to the global one.

```js
export function createApi({ fetch: doFetch = fetch, baseUrl = "" } = {}) {
  return {
    async getUser(id) {
      const res = await doFetch(`${baseUrl}/users/${id}`);
      if (!res.ok) throw new HttpError(res.status);
      return res.json();
    },
  };
}
```

The test constructs it with a fake that returns a `Response`-shaped object, and the production code stays unaware that testing exists.

A fixture-driven fake keeps tests readable:

```js
const fixtures = new Map([
  ["/users/1", { status: 200, body: { id: 1, name: "Ada" } }],
]);

const fakeFetch = async (url) => {
  const hit = fixtures.get(url);
  if (!hit) return new Response("Not found", { status: 404 });
  return new Response(JSON.stringify(hit.body), {
    status: hit.status,
    headers: { "Content-Type": "application/json" },
  });
};
```

**Reject special keys explicitly** in any recursive merge:

```js
const FORBIDDEN = new Set(["__proto__", "constructor", "prototype"]);

function safeAssign(target, source) {
  for (const key of Object.keys(source)) {
    if (FORBIDDEN.has(key)) continue;
    if (!Object.hasOwn(source, key)) continue;
    // ... recurse for plain objects, assign otherwise
  }
  return target;
}
```

`Object.keys` plus `Object.hasOwn` keeps you to own enumerable properties, which is what a data merge should touch.

The result:

```js
async function loadOrderContext(id) {
  const user = await getUser(id);
  const orders = await getOrders(user.id);
  const shipping = await getShipping(orders[0].id);
  return { user, orders, shipping };
}
```

One `try`/`catch` at the call site replaces three repeated error branches, and the sequence reads top to bottom.
